package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    /** 0 or more, with up to two decimals. */
    private static final Pattern MONEY = Pattern.compile("(\\d+(\\.\\d{0,2})?|\\.\\d{1,2})");

    /** A whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,6}");

    /** The grades that may have their own terms and grace days. */
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** The roles a permission may name. */
    private static final Set<String> ROLES = Set.of(Role.CLERK, Role.STEWARD);

    public void validate(@RequestBody SettingRequest request, Out<SettingRequest> body)
            throws InvalidSettingException {
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String value = request == null || request.value() == null ? "" : request.value().trim();
        String from = request == null || request.from() == null || !SettingRepository.isDated(key)
                ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
                from = LocalDate.parse(from).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("A setting's from-date is blank or a date (yyyy-MM-dd)");
            }
        }
        String given = from.isEmpty() ? null : from;
        if (SettingRepository.CLERK_LIMIT.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The clerk limit is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.PROOF_THRESHOLD.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The proof threshold is blank or 0.00 or more with up to two decimals");
            }
        } else if (key.startsWith(SettingRepository.PROOF_THRESHOLD_OF_GRADE)
                && GRADES.contains(key.substring(SettingRepository.PROOF_THRESHOLD_OF_GRADE.length()))) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("A grade's proof threshold is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.NOTE_THRESHOLD.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The note threshold is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.CAP.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The cap is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.POT.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The pot is blank or 0.00 or more with up to two decimals");
            }
            body.set(new SettingRequest(key, value.isEmpty() ? null : new BigDecimal(value).setScale(2).toPlainString(), null));
            return;
        } else if (SettingRepository.FLOOR.equals(key)) {
            if (!MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The floor is 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.LATE_PCT.equals(key)) {
            if (!MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The late percent is 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.TERMS.equals(key)) {
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("The terms are a whole number of days, 0 or more");
            }
            body.set(new SettingRequest(key, String.valueOf(Integer.parseInt(value)), given));
            return;
        } else if (key.startsWith(SettingRepository.TERMS_OF_GRADE)
                && GRADES.contains(key.substring(SettingRepository.TERMS_OF_GRADE.length()))) {
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("A grade's terms are blank or a whole number of days, 0 or more");
            }
            body.set(new SettingRequest(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), given));
            return;
        } else if (SettingRepository.GRACE_DAYS.equals(key)) {
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("The grace days are blank or a whole number of days, 0 or more");
            }
            body.set(new SettingRequest(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), null));
            return;
        } else if (key.startsWith(SettingRepository.GRACE_OF_GRADE)
                && GRADES.contains(key.substring(SettingRepository.GRACE_OF_GRADE.length()))) {
            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("A grade's grace days are blank or a whole number of days, 0 or more");
            }
            body.set(new SettingRequest(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), given));
            return;
        } else if (SettingRepository.POLICY_DATE.equals(key)
                || SettingRepository.PERIOD_NUMBERING_FROM.equals(key)
                || SettingRepository.ENTRY_DATE.equals(key)) {
            if (!value.isEmpty()) {
                try {
                    value = LocalDate.parse(value).toString();
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("The " + key + " setting is blank or a date (yyyy-MM-dd)");
                }
            }
            body.set(new SettingRequest(key, value.isEmpty() ? null : value, null));
            return;
        } else if (Permissions.isKey(key)) {
            List<String> roles = Permissions.roles(value);
            if (!roles.stream().allMatch(ROLES::contains)) {
                throw new InvalidSettingException("A permission is blank or a comma separated list of clerk and steward");
            }
            body.set(new SettingRequest(key, roles.isEmpty() ? null : String.join(",", roles), null));
            return;
        } else {
            throw new InvalidSettingException("Unknown setting: " + key);
        }
        body.set(new SettingRequest(key,
                value.isEmpty() ? null : new BigDecimal(value).setScale(2).toPlainString(), given));
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class ChangeSetting {
    public void set(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val SettingRequest request, SheetRepository sheets, SettingRepository settings,
            Out<Setting> setting) {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        sheets.open(id, user);
        // A dated key's value applies from its from-date, by default the sheet's today.
        LocalDate from = !SettingRepository.isDated(request.key()) ? null
                : request.from() != null ? LocalDate.parse(request.from()) : sheets.today(id);
        setting.set(settings.set(id, request.key(), request.value(), from, user));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;
import java.util.function.LongFunction;
import java.util.function.ToIntFunction;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingRepository {

    /** The clerk limit: the largest due a clerk may settle (two decimals; blank: no limit). */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The proof threshold: a claim whose due is above the one in force on its date cannot be settled
     *  or approved without a proof (two decimals; blank: none). */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** A grade's proof threshold ({@code proof-threshold-<grade>}, dated; two decimals; blank: none):
     *  a claim whose person's grade in force on its date has one in force on that date goes by it
     *  instead of the sheet's. */
    public static final String PROOF_THRESHOLD_OF_GRADE = "proof-threshold-";

    /** The note threshold: a claim whose due is above the one in force on its date cannot be opened
     *  with an empty note (two decimals; blank: none). */
    public static final String NOTE_THRESHOLD = "note-threshold";

    /** The cap: the most a person's due-total can be (two decimals; blank: no cap). */
    public static final String CAP = "cap";

    /** The pot: the sum a balanced pool's members cut between them (two decimals; blank: none; not dated). */
    public static final String POT = "pot";

    /** The floor: the least a claim's live due can be (two decimals). */
    public static final String FLOOR = "floor";

    /** The terms: the number of business days after its date by which a claim is due (a whole number). */
    public static final String TERMS = "terms";

    /** A grade's own terms ({@code terms-<grade>}; blank: the sheet's terms). */
    public static final String TERMS_OF_GRADE = "terms-";

    /** The late percent: the share of an overdue claim's figure it gains for every full 30 days
     *  it is overdue (two decimals). */
    public static final String LATE_PCT = "late-pct";

    /** The policy date (yyyy-MM-dd; blank: the sheet's today): a claim dated before it rounds half
     *  up, one on or after it half to even. */
    public static final String POLICY_DATE = "policy-date";

    /** The period numbering date (yyyy-MM-dd; blank: off): once the sheet's today is on or after it,
     *  a claim opened is numbered within its period. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The entry date (yyyy-MM-dd; blank: off): while set, a new claim with no date of its own takes
     *  it instead of the sheet's today. */
    public static final String ENTRY_DATE = "entry-date";

    /** The grace days (a whole number; blank: off): when the sheet's today changes, an open period
     *  whose to-date plus them is before the new today is closed. */
    public static final String GRACE_DAYS = "grace-days";

    /** A grade's grace days ({@code grace-<grade>}, dated; a whole number; blank: none): a claim whose
     *  person's grade in force on its date has them in force on that date is overdue, and gains its late
     *  charge, counting from its due-by plus them. */
    public static final String GRACE_OF_GRADE = "grace-";

    /** The late percent until it is first set. */
    public static final String DEFAULT_LATE_PCT = "0.00";

    /** The terms until they are first set. */
    public static final String DEFAULT_TERMS = "14";

    /** The floor until it is first set. */
    public static final String DEFAULT_FLOOR = "1.00";

    /** Whether a key is dated: every key that carries a figure (the policy date, the period
     *  numbering date, the grace days, the pot and the permission matrix are not). */
    public static boolean isDated(String key) {
        return !POLICY_DATE.equals(key) && !GRACE_DAYS.equals(key) && !PERIOD_NUMBERING_FROM.equals(key)
                && !ENTRY_DATE.equals(key) && !POT.equals(key) && !Permissions.isKey(key);
    }

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;
    private final PersonRepository people;

    public SettingRepository(JdbcTemplate jdbc, SheetRepository sheets, PersonRepository people) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.people = people;
    }

    /** Every value recorded for the sheet's settings, by key, then by from-date (none first). */
    public List<Setting> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting, val, from_date FROM sheet_setting WHERE sheet_id = ? "
                + "ORDER BY setting, from_key", (rs, n) -> row(rs), sheetId);
    }

    private static Setting row(ResultSet rs) throws SQLException {
        LocalDate from = rs.getObject("from_date", LocalDate.class);
        return new Setting(rs.getString("sheet_id"), rs.getString("setting"),
                rs.getString("val") == null ? "" : rs.getString("val"), from == null ? null : from.toString());
    }

    /** The values recorded for a key, with its value before every from-date ({@code start}). */
    public DatedSetting dated(String sheetId, String key, String start) {
        return new DatedSetting(jdbc.query("SELECT sheet_id, setting, val, from_date FROM sheet_setting "
                + "WHERE sheet_id = ? AND setting = ?", (rs, n) -> row(rs), sheetId, key), start);
    }

    /** The values recorded for a key as they stood at the end of the date (each as the last value
     *  recorded while the sheet's today was on or before the date left it), with its value before
     *  every from-date ({@code start}). */
    public DatedSetting datedAsOf(String sheetId, String key, String start, LocalDate asOf) {
        return new DatedSetting(jdbc.query("SELECT sheet_id, setting, val, from_date FROM setting_history h "
                + "WHERE h.sheet_id = ? AND h.setting = ? AND h.id = (SELECT MAX(h2.id) FROM setting_history h2 "
                + "WHERE h2.sheet_id = h.sheet_id AND h2.setting = h.setting AND h2.from_key = h.from_key "
                + "AND (h2.on_date IS NULL OR h2.on_date <= ?))", (rs, n) -> row(rs), sheetId, key, asOf), start);
    }

    /** The sheet's cap in force on the date as it stood then; null when there was none. */
    public BigDecimal capAsOf(String sheetId, LocalDate asOf) {
        String value = datedAsOf(sheetId, CAP, null, asOf).on(asOf.toString());
        return value == null ? null : new BigDecimal(value);
    }

    /** What a claim's late charge and rounding went by at the end of the date, the date standing in
     *  for the sheet's today. */
    public Dues.Late lateAsOf(String sheetId, LocalDate asOf) {
        String policy = datedAsOf(sheetId, POLICY_DATE, null, asOf).on("9999-12-31");
        return new Dues.Late(datedAsOf(sheetId, LATE_PCT, DEFAULT_LATE_PCT, asOf), asOf,
                policy == null ? asOf : LocalDate.parse(policy),
